    "COOKIE_SECURE", "true" if HOST not in {"127.0.0.1", "localhost"} else "false"
).lower() not in {"0", "false", "no"}
LOGIN_WINDOW_SECONDS = 15 * 60
LOGIN_MAX_ATTEMPTS = 5
LOGIN_LOCK_SECONDS = 15 * 60
