equipment({ limit: 1000 }); const units = Array.isArray(refreshed) ? refreshed : (refreshed.equipment || refreshed.items || []); equipment = groupUnits(units); renderBrands(); closeEditor(); render(document.querySelector('.admin-tabs .selected')?.dataset.filter || 'All'); } catch (error) { mlmUiError(error.message); } }; dialog.querySelector('[name="name"]').focus(); };
